// Kill switch for the old Jekyll/Chirpy PWA service worker, which was registered at /sw.min.js
// and served the old site from its offline cache. Browsers re-check this URL for updates; when
// they get this version it takes over, deletes every cache, unregisters itself and reloads open
// tabs onto the live site. Keep this file: past visitors may only return months from now.
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((k) => caches.delete(k)));
      await self.registration.unregister();
      const tabs = await self.clients.matchAll({ type: 'window' });
      tabs.forEach((tab) => tab.navigate(tab.url));
    })(),
  );
});
